	('5ac2187a-bbc1-444f-aa29-e0d2d0924db5', 'AI Tools for Teachers', 'AITT2026-19', 'Free live webinar designed for teachers to learn practical AI tools for lesson planning, worksheets, quizzes, communication, and classroom productivity.', 'https://storage-sp.rareminds.in/courses/AITT2026-19/thumbnail/image (1).png', 'Active', '1 Session', 0, 0, 0, 0, 0, NULL, '2026-05-26 10:23:09.088161+00', '2026-05-26 10:23:09.088161+00', NULL, '["Use ChatGPT for lesson planning", "Create worksheets and quizzes", "Write parent messages and school notices", "Create visuals using Canva/Gamma", "Use AI safely in teaching"]', NULL, NULL, 'Teacher Training', 'pending', NULL, NULL, NULL, NULL, NULL, 'technical', NULL, NULL, 'teacher', 'freemium', 'webinar', '2026-05-19'),
	('11e7c069-6d02-449e-a0a8-1145104aad01', 'Smart Spending - Real-World ', 'G9_004', 'Practice-based course for Grade 9 to build financial literacy capability through activities, reflection, and real-world tasks.', NULL, 'Active', '30', 1, 0, 0, 2, 2, NULL, '2026-03-03 11:42:58.856981+00', '2026-05-26 10:32:14.340428+00', NULL, '["Use money concepts", "budget and plan", "make informed choices", "understand value and risk."]', NULL, 0, 'Financial Literacy', 'pending', NULL, NULL, NULL, NULL, NULL, 'soft', NULL, NULL, 'high_school', 'premium', 'course', NULL),
	('02e65a5e-99db-4d33-b57d-96a8ad1c2ac9', 'AI Tools for Teachers', 'AITT2026-14', 'Free live webinar designed for teachers to learn practical AI tools for lesson planning, worksheets, quizzes, communication, and classroom productivity.', 'https://storage-sp.rareminds.in/courses/AITT2026-19/thumbnail/image (1).png', 'Active', '1 Session', 1, 0, 0, 0, 0, NULL, '2026-05-26 10:23:09.088161+00', '2026-05-26 10:26:58.604519+00', NULL, '["Use ChatGPT for lesson planning", "Create worksheets and quizzes", "Write parent messages and school notices", "Create visuals using Canva/Gamma", "Use AI safely in teaching"]', NULL, NULL, 'Teacher Training', 'pending', NULL, NULL, NULL, NULL, NULL, 'technical', NULL, NULL, 'teacher', 'freemium', 'webinar', '2026-05-14'),
