	('b01ad104-cbba-47eb-92c0-329a6ae53d0a', 'Product Build Challenge: Level 1 ', 'G6_014', 'Practice-based course for Grade 6 to build project lab capability through activities, reflection, and real-world tasks.', NULL, 'Active', '40', 0, 0, 0, 1, 1, NULL, '2026-03-03 11:42:58.856981+00', '2026-05-26 10:32:14.340428+00', NULL, '["Deliver a project artifact", "collaborate", "present outcomes", "reflect and iterate based on feedback."]', NULL, 0, 'Project Lab', 'pending', NULL, NULL, NULL, NULL, NULL, 'technical', NULL, NULL, 'middle_school', 'premium', 'course', NULL),
