	('7b4fee68-2c37-4d79-817a-25dcd7fc069f', 'c3d4e5f6-a7b8-49c0-d1e2-f3a4b5c6d7e8', NULL, 'Client changes requirements late. You:', 'sjt', '["Refuse; say it''s too late.", "Ask for priority changes and renegotiate timeline.", "Agree to everything without checking feasibility.", "Ignore and continue old plan."]', '"Ask for priority changes and renegotiate timeline."', 27, true, '2026-05-26 10:06:51.742856+00', '2026-05-26 10:06:51.742856+00', NULL, '{"best": "Ask for priority changes and renegotiate timeline.", "worst": "Ignore and continue old plan.", "scenario": "Client changes requirements late"}', '{"part": "B", "applicable_grades": ["after10", "after12", "college"]}'),
	('61304246-4810-46dc-94c1-0f3866035436', 'c3d4e5f6-a7b8-49c0-d1e2-f3a4b5c6d7e8', NULL, 'You made an error in a submission. You:', 'sjt', '["Hide it and hope nobody notices.", "Inform mentor, correct quickly, explain learning.", "Blame the rubric.", "Quit the task."]', '"Inform mentor, correct quickly, explain learning."', 28, true, '2026-05-26 10:06:51.742856+00', '2026-05-26 10:06:51.742856+00', NULL, '{"best": "Inform mentor, correct quickly, explain learning.", "worst": "Hide it and hope nobody notices.", "scenario": "You made an error in a submission"}', '{"part": "B", "applicable_grades": ["after10", "after12", "college"]}'),
	('dadd0616-7d2a-4634-9b54-0f2e8992cc16', 'c3d4e5f6-a7b8-49c0-d1e2-f3a4b5c6d7e8', NULL, 'Two teammates are in conflict. You:', 'sjt', '["Take sides with your friend.", "Facilitate a calm discussion on facts and goals.", "Tell them to grow up.", "Leave the team."]', '"Facilitate a calm discussion on facts and goals."', 29, true, '2026-05-26 10:06:51.742856+00', '2026-05-26 10:06:51.742856+00', NULL, '{"best": "Facilitate a calm discussion on facts and goals.", "worst": "Tell them to grow up.", "scenario": "Two teammates are in conflict"}', '{"part": "B", "applicable_grades": ["after10", "after12", "college"]}'),
	('242df483-6ef0-4c4d-9f4e-72ea170807be', 'c3d4e5f6-a7b8-49c0-d1e2-f3a4b5c6d7e8', NULL, 'You are assigned a task you do not know. You:', 'sjt', '["Delay till last day.", "Learn basics fast, ask guidance early, deliver in parts.", "Say no immediately.", "Copy from internet without understanding."]', '"Learn basics fast, ask guidance early, deliver in parts."', 30, true, '2026-05-26 10:06:51.742856+00', '2026-05-26 10:06:51.742856+00', NULL, '{"best": "Learn basics fast, ask guidance early, deliver in parts.", "worst": "Copy from internet without understanding.", "scenario": "You are assigned a task you do not know"}', '{"part": "B", "applicable_grades": ["after10", "after12", "college"]}'),
